Object.keys(KD).forEach(function(k){(BYF[KD[k].f]=BYF[KD[k].f]||[]).push(k);});
TN.KINDS=Object.keys(KD);
var TAG={apathy:'無関心',fear:'恐怖',fiance:'許嫁',dep:'執着（依存）',hatelove:'執着（愛憎）',hate:'憎悪',guilt:'負い目',oshi:'推し',mistress:'愛人',comrade:'仲間'};
var SKIP= /クライマックス|生贄|罰ゲーム|結末|エピローグ|解決|脱出|最後|最期|真相|推理|吹雪が止んだ|踏破|帰還|全滅|時間切れ|見つかった|解除|その後|後日談|降り立つ|力尽き|終わり/;
var LOVE_T= /^(lover|crush|almost|honmei|fwb|mate|fated|yan|spouse|fiance)$/,DIR_LOVE= /^(crush|honmei|yan)$/;
function fiFeel(t,i){
var f=i===t.a?(t.feelA!=null?t.feelA:t.feel):(t.feelB!=null?t.feelB:t.feel2!=null?t.feel2:t.cold||t.feel);
if(f&&typeof f==='object')f=f[i];
return f==='eager'||f==='refuse'||f==='unsure'?f:'unsure';
}
TN.fiFeel=fiFeel;
function loveOther(S,x,ex){
var hit=(S.tnAll||[]).some(function(t){
if(!LOVE_T.test(t.type)||t.a===t.b)return false;
if(t.type==='fiance')return false;
if(DIR_LOVE.test(t.type))return t.a===x.i&&t.b!==ex.i;
return(t.a===x.i&&t.b!==ex.i)||(t.b===x.i&&t.a!==ex.i);
});
if(hit)return true;
if(Array.isArray(S.lovers)&&S.lovers.some(function(pr){return(pr[0]===x.i&&pr[1]!==ex.i)||(pr[1]===x.i&&pr[0]!==ex.i);}))return true;
if(S.rom)return Object.keys(S.rom).some(function(k){if(!S.rom[k])return false;var ij=k.split('-').map(Number);return(ij[0]===x.i&&ij[1]!==ex.i)||(ij[1]===x.i&&ij[0]!==ex.i);});
return false;
}
function pkey(a,b){return a.i<b.i?a.i+'-'+b.i:b.i+'-'+a.i;}
function cold(S,a,b){return(S.tnAll||[]).some(function(t){return(t.type==='fear'||t.type==='apathy')&&on(t.type)&&((t.a===a.i&&t.b===b.i)||(t.a===b.i&&t.b===a.i));});}
function apa(S,a,b){return(S.tnAll||[]).some(function(t){return t.type==='apathy'&&on('apathy')&&t.a===a.i&&t.b===b.i;});}
function holders(t,P){
var A=P[t.a],B=P[t.b],o=[];
if(!A|| !B||A===B|| !on(t.type))return o;
switch(t.type){
case'apathy':o.push([A,B,'apathy']);break;
case'fear':o.push([A,B,'fear']);break;
case'fiance':o.push([A,B,'fiance'],[B,A,'fiance']);break;
case'yan':if(t.sub==='dep')o.push([A,B,'dep']);else if(t.sub==='hatelove')o.push([A,B,'hatelove']);break;
case'enemy':if(t.grade==='hate')o.push([A,B,'hate']);break;
case'benefactor':if(t.feel==='guilt')o.push([B,A,'guilt']);break;
case'fond':if(t.mode==='oshi')o.push([A,B,'oshi']);break;
case'fwb':if(t.mode==='mistress')o.push([A,B,'mistress'],[B,A,'mistress']);break;
case'comrade':o.push([A,B,'comrade'],[B,A,'comrade']);break;
}
return o;
}
TN.holders=holders;
function choose(S,P,live,TX,rng){
var opts=[];
(S.tnTies||[]).forEach(function(t){
holders(t,P).forEach(function(h){
var a=h[0],b=h[1],f=h[2];
if(live.indexOf(a)<0||live.indexOf(b)<0)return;
if(/^(fiance|dep|oshi|mistress|guilt|comrade)$/.test(f)&&cold(S,a,b))return;
if(/^(hate|hatelove)$/.test(f)&&apa(S,a,b))return;
var pk=pkey(a,b),dk=a.i+'>'+b.i,used=S.tnUsed[dk]||[];
if(f==='fiance'&&S.tnBroke[pk])return;
var fe=f==='fiance'?fiFeel(t,a.i):'';
if(fe==='eager'&&(!(HK.canLove&&HK.canLove(a,b))||HK.lockOut(a,b)))fe='unsure';
(BYF[f]||[]).forEach(function(k){
if(!TX[k]||used.indexOf(k)>=0)return;
if(k==='fiE'&&fe!=='eager')return;
if(k==='fiU'&&fe==='eager')return;
if(k==='fiB'&& !(fe==='refuse'&&loveOther(S,a,b)))return;
var body=TX[k],need3=body.indexOf('{c}')>=0;
var cs=need3?live.filter(function(q){return q!==a&&q!==b;}):[];
if(need3&& !cs.length&& !TX.cNPC)return;
var D=KD[k];
opts.push({a:a,b:b,k:k,f:f,fe:fe,pk:pk,dk:dk,c:cs.length?cs[rng.int(cs.length)]:null,w:Math.max(0.05,D.w?D.w(a,S):1)});
});
});
});
return opts.length?HK.weighted(rng,opts,function(o){return o.w;}):null;
}
function fill(t,m){return String(t).replace(/\{(\w+)\}/g,function(x,k){return m[k]!=null?m[k]:x;});}
function end(t){return/[。」！？]$/.test(t)?t:t+'。';}
function make(S,o,TX,pick){
(S.tnUsed[o.dk]=S.tnUsed[o.dk]||[]).push(o.k);
S.tnN=(S.tnN||0)+1;
if(o.k==='fiB')S.tnBroke[o.pk]=1;
var m={a:o.a.name,b:o.b.name,c:o.c?o.c.name:TX.cNPC||'誰か'};
var T=o.f==='fiance'?ATT.fi[o.k==='fiB'?'refuse':o.fe]:ATT[o.f];
var line=T?(T[per(o.a)]||T.gentle):null;
var text=end(fill(pick(L(TX[o.k])),m))+(line?end(fill(pick(line),m)):'');
var tag=o.k==='fiB'?'破談':TAG[o.f];
return{actors:o.c?[o.a,o.b,o.c]:[o.a,o.b],tag:tag,text:text,why:o.a.name+'→'+o.b.name+'：'+KD[o.k].why+'（'+TAG[o.f]+'）'};
}
TN.choose=choose;TN.make=make;
function pickTies(input,P){
var all=(input.ties||[]).filter(function(t){return t&&P[t.a]&&P[t.b]&&t.a!==t.b;});
return{all:all,use:all.filter(function(t){return USE.test(t.type)&&t.noev!=='off'&&holders(t,P).length>0;})};
}
