A.FEAT_PLAY=A.RACE_PLAY={BOT:BOT,BOT_E:BOT_E,TOP:TOP,HOLE:HOLE,HOLE_UN:HOLE_UN};
A.NOTE_PLAY={BOT:BOT.note,BOT_E:BOT_E.note,TOP:TOP.note,HOLE:HOLE.note,HOLE_UN:HOLE_UN.note};
var INS= /沈め|沈む|繋が|挿|貫|呑み込|突く|突き|突かれ|奥|中で|中に|注が|注ぎ|受け入れ|どくどく|脈打|打ちつけ|叩きつけ|腰を落と|腰を沈め|腰を揺ら|腰を回|熱を受け止め|締めつけ|締め付け|ナカ|根元まで|迎え入れ|咥え込/;
function noteOf(c){return(c&&(c.raceNote||(c.src&&c.src.raceNote)))||'';}
function fill(t,v){return t.replace(/\{(\w+)\}/g,function(m,k){return v[k]!=null?v[k]:m;});}
function modeOf(T,U){
var P=HK.Pos;
if(!P|| !P.isF)return'mf';
return P.isF(T,U)?(P.isF(U,T)?'ff':'fm'):'mf';
}
function ownOf(o){
var w=o&&o.owner;
if(w&&typeof w==='object')return w;
return A.curOwner&&typeof A.curOwner==='object'?A.curOwner:null;
}
function recOf(own){return Array.isArray(own.log)?own.log.length:(own._featCalls||0);}
function noIns(ng){return function(s){return!(ng&&INS.test(s));};}
function linesOf(role,k,kind,mode,ero,ng){
var l;
if(role==='bot'){
var b=BOT[k];
if(!b)return[];
l=(b[kind]&&b[kind][mode])||[];
if(kind==='climax'&&ero&&BOT_E[k]&&BOT_E[k][mode])l=BOT_E[k][mode].concat(l);
l=l.filter(noIns(ng));
if(!l.length)l=b.fore[mode].filter(noIns(ng));
}else{
var t=TOP[k];
if(!t)return[];
l=(t[kind]||[]).filter(noIns(ng));
if(!l.length)l=t.fore.filter(noIns(ng));
}
return l;
}
function barred(k,partner){return k==='fang'&&(A.feat(partner,'fang')||A.feat(partner,'trans'));}
var nightSeq=0;
function newNight(own,T,U){
var N={key:T.name+'\u0001'+U.name,id: ++nightSeq,who:{},used:{},last:''};
if(own){
N.rec=N.rec0=recOf(own);
[T,U].forEach(function(x){
var l=own._featLast&&own._featLast[x.name];
if(l&&own._featRec===N.rec&&l.at===N.rec){N.who[x.name]=1;(N.used[x.name]={})[l.feat]=1;}
});
own._featNight=N;
}
return N;
}
function nightOf(own,T,U){
var n=own&&own._featNight;
if(n&&n.key===T.name+'\u0001'+U.name&&n.rec===recOf(own))return n;
return newNight(own,T,U);
}
function peekKey(own,x,partner,role,kind,mode,ero,ng,N,pick){
if(N.last===x.name||(N.who[x.name]||0)>=2)return'';
var lp=own&&own._featLast&&own._featLast[x.name];
if(lp&&N.rec0!=null&&lp.at!==N.rec0&&N.rec0-lp.at<(A.FEAT_GAP||3))return'';
var used=N.used[x.name]||{};
var keys=function(k){return!used[k]&& !barred(k,partner)&&linesOf(role,k,kind,mode,ero,ng).length>0;};
var po=null;
if(own){
po=Object.create(own);
po._featRec= -1;
po._featLast={};
var l0=own._featLast&&own._featLast[x.name];
if(l0&& !N.who[x.name])po._featLast[x.name]={at: -1e9,feat:l0.feat};
}
return A.featPick(po,x,{kind:'play',pick:pick,peek:true,keys:keys});
}
A.racePlay=function(T,U,kind,pick,o){
if(HK.SAFE_ON|| !T|| !U||T===U||typeof pick!=='function')return'';
if(!/^(?:fore|mid|climax|after)$/.test(kind))return'';
if(!A.featKeys(T).length&& !A.featKeys(U).length)return'';
o=o||{};
var P=HK.Pos,ng= !!(P&&P.noGen&&(P.noGen(T)||P.noGen(U)));
var mode= /^(?:mf|ff|fm)$/.test(o.mode||'')?o.mode:modeOf(T,U);
if(P&&P.hasM&&((mode==='mf'&& !P.hasM(T))||(mode==='fm'&& !P.hasM(U))))ng=true;
var own=ownOf(o),N=o._night||nightOf(own,T,U),ero= !!o.ero,cand=[];
[[U,'bot',T],[T,'top',U]].forEach(function(e){
var k=peekKey(own,e[0],e[2],e[1],kind,mode,ero,ng,N,pick);
if(k)cand.push({x:e[0],role:e[1],k:k});
});
if(!cand.length){N.last='';return'';}
var it=cand.length===1?cand[0]:pick(cand);
var l=linesOf(it.role,it.k,kind,mode,ero,ng),pf=own&&A.raceFresh?A.raceFresh(own,pick):pick;
var s=fill(pf(l)||'',{t:T.name,u:U.name,note:noteOf(it.x)});
if(!s){N.last='';return'';}
A.featUse(own,it.x,it.k,{kind:'play'});
N.who[it.x.name]=(N.who[it.x.name]||0)+1;
(N.used[it.x.name]||(N.used[it.x.name]={}))[it.k]=1;
N.last=it.x.name;
if(own)N.rec=recOf(own);
if(A.raceLog)A.raceLog.push({kind:'play',stage:kind,who:it.x.name,feat:it.k,role:it.role,night:N.id,para:o._para!=null?o._para: -1,race:A.raceOf(it.x),mode:ng?'ng':mode,ero:ero,t:T.name,u:U.name,text:s});
return s;
};
A.raceWeave=function(arr,T,U,pick,idx,o){
if(!arr|| !idx||HK.SAFE_ON|| !T|| !U||(!A.featKeys(T).length&& !A.featKeys(U).length))return arr;
o=o||{};
var own=ownOf(o),N=newNight(own,T,U),done={};
['fore','mid','climax','after'].forEach(function(k){
var i=idx[k],ok=function(j){return j!=null&&j>=0&&j<arr.length&&typeof arr[j]==='string'&& !!arr[j].trim();};
if(Array.isArray(i))i=i.filter(ok)[0];
if(!ok(i)||done[i])return;
var o2={};for(var p in o)if(Object.prototype.hasOwnProperty.call(o,p))o2[p]=o[p];
o2._night=N;o2._para=i;
var s=A.racePlay(T,U,k,pick,o2);
if(s){arr[i]=arr[i].replace(/\s+$/,'')+s;done[i]=1;}
});
return arr;
};
A.raceHole=function(b,h,kind,pick,live){
if(HK.SAFE_ON|| !b|| !h||typeof pick!=='function')return'';
if(live!==false&& !/^(?:pen|finger)$/.test(kind))return'';
var P=HK.Pos;
if(P&&P.noGen&&(P.noGen(b)||P.noGen(h)))return'';
var tb=function(k){return live===false?HOLE_UN[k]:HOLE[k]&&HOLE[k][kind];};
var k=A.featPick(null,h,{kind:'hole',pick:pick,peek:true,keys:function(x){var l=tb(x);return!!(l&&l.length);}});
if(!k)return'';
var s=fill(pick(tb(k))||'',{t:b.name,u:h.name,note:noteOf(h)});
if(!s)return'';
A.featUse(null,h,k,{kind:'hole'});
if(A.raceLog)A.raceLog.push({kind:'play',stage:'mid',who:h.name,feat:k,role:'bot',night: -1,para: -1,race:A.raceOf(h),mode:'hole-'+kind,ero:false,t:b.name,u:h.name,text:s});
return s;
};
